initJs:
function(container, apiUrl, tables) {
  let correlationResults = [];
  let selectedCorrelation = null;

  // 店舗データを読み込んでドロップダウンに設定
  async function loadStores() {
    const storeSelect = container.querySelector('#store-select');
    try {
      const stores = await window.aivicApi.list(1); // 店舗マスタのインデックス
      if (stores) {
        stores.forEach(store => {
          if (store.有効フラグ) {
            const option = document.createElement('option');
            option.value = store.店舗ID;
            option.textContent = `${store.店舗名} (${store.店舗コード})`;
            storeSelect.appendChild(option);
          }
        });
      }
    } catch (error) {
      console.error('店舗データの読み込みに失敗しました:', error);
    }
  }

  // 商品カテゴリのチェックボックスを生成
  function setupCategoryCheckboxes() {
    const categoryContainer = container.querySelector('#category-checkboxes');
    const categories = ['食品', '飲料', '日用品', '衣料品', '家電', 'その他'];

    categories.forEach(category => {
      const label = document.createElement('label');
      const checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.value = category;
      checkbox.className = 'category-checkbox';

      label.appendChild(checkbox);
      label.appendChild(document.createTextNode(category));
      categoryContainer.appendChild(label);
    });
  }

  // 全選択チェックボックスの処理
  function setupSelectAllCategories() {
    const selectAllCheckbox = container.querySelector('#select-all-categories');
    const categoryCheckboxes = container.querySelectorAll('.category-checkbox');

    selectAllCheckbox.addEventListener('change', function() {
      categoryCheckboxes.forEach(checkbox => {
        checkbox.checked = this.checked;
      });
    });

    categoryCheckboxes.forEach(checkbox => {
      checkbox.addEventListener('change', function() {
        const allChecked = Array.from(categoryCheckboxes).every(cb => cb.checked);
        const someChecked = Array.from(categoryCheckboxes).some(cb => cb.checked);
        selectAllCheckbox.checked = allChecked;
        selectAllCheckbox.indeterminate = someChecked && !allChecked;
      });
    });
  }

  // バリデーション関数
  function validateAnalysisConditions() {
    const startDate = container.querySelector('#analysis-start-date').value;
    const endDate = container.querySelector('#analysis-end-date').value;
    const storeId = container.querySelector('#store-select').value;
    const selectedCategories = Array.from(container.querySelectorAll('.category-checkbox:checked'));
    const selectedFactors = Array.from(container.querySelectorAll('.analysis-factor:checked'));

    if (!startDate) {
      alert('期間を選択してください（開始日）');
      return false;
    }

    if (!endDate) {
      alert('期間を選択してください（終了日）');
      return false;
    }

    if (new Date(startDate) > new Date(endDate)) {
      alert('開始日は終了日より前の日付を選択してください');
      return false;
    }

    if (!storeId) {
      alert('店舗を選択してください');
      return false;
    }

    if (selectedCategories.length === 0) {
      alert('商品カテゴリを選択してください');
      return false;
    }

    if (selectedFactors.length === 0) {
      alert('分析要因を選択してください');
      return false;
    }

    return true;
  }

  // 相関分析の実行
  async function executeCorrelationAnalysis() {
    if (!validateAnalysisConditions()) {
      return;
    }

    const loadingOverlay = container.querySelector('#loading-overlay');
    loadingOverlay.classList.remove('hidden');

    try {
      const startDate = container.querySelector('#analysis-start-date').value;
      const endDate = container.querySelector('#analysis-end-date').value;
      const storeId = container.querySelector('#store-select').value;
      const selectedCategories = Array.from(container.querySelectorAll('.category-checkbox:checked')).map(cb => cb.value);
      const selectedFactors = Array.from(container.querySelectorAll('.analysis-factor:checked')).map(cb => cb.value);

      // 売上実績データを取得
      const salesData = await window.aivicApi.list(3); // 売上実績データのインデックス
      if (!salesData || salesData.length === 0) {
        alert('指定された期間にはデータが存在しません。期間を見直してください。');
        return;
      }

      // 外部要因データを取得
      const weatherData = await window.aivicApi.list(4); // 天候データ
      const eventData = await window.aivicApi.list(5); // イベントデータ
      const seasonData = await window.aivicApi.list(6); // 季節情報データ

      // 相関分析を実行（模擬データ）
      correlationResults = generateCorrelationResults(selectedFactors);

      // 結果を表示
      displayCorrelationResults();
      drawCharts();
      displayStatistics();
      displaySummary();

      // 結果エリアを表示
      container.querySelector('#analysis-results').style.display = 'block';

    } catch (error) {
      console.error('分析実行エラー:', error);
      alert('分析の実行中にエラーが発生しました。');
    } finally {
      loadingOverlay.classList.add('hidden');
    }
  }

  // 相関分析結果の生成（模擬データ）
  function generateCorrelationResults(factors) {
    const results = [];

    factors.forEach(factor => {
      let factorName, correlation, significance, evaluation;

      switch(factor) {
        case 'weather':
          factorName = '気温';
          correlation = (Math.random() * 0.8 + 0.1).toFixed(3);
          significance = Math.random() < 0.7 ? '有意' : '非有意';
          evaluation = parseFloat(correlation) > 0.5 ? '強い' : parseFloat(correlation) > 0.3 ? '中程度' : '弱い';
          break;
        case 'event':
          factorName = 'イベント';
          correlation = (Math.random() * 0.6 + 0.2).toFixed(3);
          significance = Math.random() < 0.8 ? '有意' : '非有意';
          evaluation = parseFloat(correlation) > 0.5 ? '強い' : parseFloat(correlation) > 0.3 ? '中程度' : '弱い';
          break;
        case 'season':
          factorName = '季節性';
          correlation = (Math.random() * 0.7 + 0.2).toFixed(3);
          significance = Math.random() < 0.9 ? '有意' : '非有意';
          evaluation = parseFloat(correlation) > 0.5 ? '強い' : parseFloat(correlation) > 0.3 ? '中程度' : '弱い';
          break;
      }

      results.push({
        factor: factorName,
        correlation: correlation,
        significance: significance,
        evaluation: evaluation
      });
    });

    return results;
  }

  // 相関係数表の表示
  function displayCorrelationResults() {
    const tbody = container.querySelector('#correlation-tbody');
    tbody.innerHTML = correlationResults.map((result, index) => `
      <tr class="correlation-row" data-index="${index}">
        <td>${result.factor}</td>
        <td>${result.correlation}</td>
        <td>${result.significance}</td>
        <td>${result.evaluation}</td>
      </tr>
    `).join('');
  }

  // グラフの描画
  function drawCharts() {
    drawScatterChart();
    drawTimeSeriesChart();
    drawHeatmapChart();
  }

  // 散布図の描画
  function drawScatterChart() {
    const canvas = container.querySelector('#scatter-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 背景
    ctx.fillStyle = '#1a2332';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // 軸の描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(50, 50);
    ctx.lineTo(50, canvas.height - 50);
    ctx.lineTo(canvas.width - 50, canvas.height - 50);
    ctx.stroke();

    // データポイントの描画
    ctx.fillStyle = '#4a90e2';
    for (let i = 0; i < 50; i++) {
      const x = 50 + Math.random() * (canvas.width - 100);
      const y = 50 + Math.random() * (canvas.height - 100);
      ctx.beginPath();
      ctx.arc(x, y, 3, 0, 2 * Math.PI);
      ctx.fill();
    }

    // ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px Arial';
    ctx.fillText('売上数量', canvas.width / 2 - 30, canvas.height - 20);
    ctx.save();
    ctx.translate(20, canvas.height / 2);
    ctx.rotate(-Math.PI / 2);
    ctx.fillText('外部要因', -30, 0);
    ctx.restore();
  }

  // 時系列チャートの描画
  function drawTimeSeriesChart() {
    const canvas = container.querySelector('#timeseries-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 背景
    ctx.fillStyle = '#1a2332';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // 軸の描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(50, 50);
    ctx.lineTo(50, canvas.height - 50);
    ctx.lineTo(canvas.width - 50, canvas.height - 50);
    ctx.stroke();

    // 時系列データの描画
    ctx.strokeStyle = '#4a90e2';
    ctx.lineWidth = 2;
    ctx.beginPath();

    const points = 30;
    for (let i = 0; i < points; i++) {
      const x = 50 + (i / (points - 1)) * (canvas.width - 100);
      const y = canvas.height - 50 - Math.sin(i * 0.3) * 50 - Math.random() * 100;

      if (i === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    }
    ctx.stroke();

    // ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px Arial';
    ctx.fillText('時間', canvas.width / 2 - 15, canvas.height - 20);
    ctx.save();
    ctx.translate(20, canvas.height / 2);
    ctx.rotate(-Math.PI / 2);
    ctx.fillText('売上', -15, 0);
    ctx.restore();
  }

  // ヒートマップの描画
  function drawHeatmapChart() {
    const canvas = container.querySelector('#heatmap-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 背景
    ctx.fillStyle = '#1a2332';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    const cellSize = 40;
    const startX = 100;
    const startY = 80;
    const rows = 6;
    const cols = 6;

    // ヒートマップセルの描画
    for (let i = 0; i < rows; i++) {
      for (let j = 0; j < cols; j++) {
        const intensity = Math.random();
        const red = Math.floor(255 * intensity);
        const blue = Math.floor(255 * (1 - intensity));

        ctx.fillStyle = `rgb(${red}, 100, ${blue})`;
        ctx.fillRect(startX + j * cellSize, startY + i * cellSize, cellSize - 1, cellSize - 1);

        // 相関係数値の表示
        ctx.fillStyle = '#ffffff';
        ctx.font = '10px Arial';
        ctx.textAlign = 'center';
        ctx.fillText(intensity.toFixed(2), startX + j * cellSize + cellSize/2, startY + i * cellSize + cellSize/2 + 3);
      }
    }

    // ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px Arial';
    ctx.textAlign = 'left';
    const labels = ['売上', '気温', '湿度', '降水量', 'イベント', '季節'];
    labels.forEach((label, i) => {
      ctx.fillText(label, 10, startY + i * cellSize + cellSize/2 + 3);
      ctx.fillText(label, startX + i * cellSize + 5, startY - 10);
    });
  }

  // 統計値の表示
  function displayStatistics() {
    const statsGrid = container.querySelector('#stats-grid');

    const stats = [
      { label: '平均相関係数', value: '0.456' },
      { label: '最大相関係数', value: '0.782' },
      { label: '最小相関係数', value: '0.123' },
      { label: '標準偏差', value: '0.234' },
      { label: 'サンプル数', value: '1,250' },
      { label: '有意な相関数', value: '3' }
    ];

    statsGrid.innerHTML = stats.map(stat => `
      <div class="stat-item">
        <div class="stat-value">${stat.value}</div>
        <div class="stat-label">${stat.label}</div>
      </div>
    `).join('');
  }

  // 分析結果サマリーの表示
  function displaySummary() {
    const summaryContainer = container.querySelector('#analysis-summary');

    const summary = `
      <h4>分析結果概要</h4>
      <p>実行した相関分析により、以下の知見が得られました：</p>
      <ul>
        <li>気温と売上の間に中程度の正の相関が確認されました（r=0.456）</li>
        <li>イベント要因は売上に強い影響を与えることが示されました（r=0.782）</li>
        <li>季節性要因も需要予測において重要な指標となります（r=0.634）</li>
        <li>統計的に有意な相関関係が3つの要因で確認されました</li>
      </ul>
      <p>これらの結果を需要予測モデルに組み込むことで、予測精度の向上が期待できます。</p>
    `;

    summaryContainer.innerHTML = summary;
  }

  // CSVエクスポート
  function exportToCSV() {
    if (correlationResults.length === 0) {
      alert('エクスポートするデータがありません。');
      return;
    }

    const headers = ['要因', '相関係数', '有意性レベル', '評価'];
    const csvContent = [
      '\uFEFF' + headers.join(','),
      ...correlationResults.map(row => 
        [row.factor, row.correlation, row.significance, row.evaluation].join(',')
      )
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `correlation_analysis_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 条件クリア
  function clearConditions() {
    container.querySelector('#analysis-start-date').value = '';
    container.querySelector('#analysis-end-date').value = '';
    container.querySelector('#store-select').value = '';

    container.querySelectorAll('.category-checkbox').forEach(cb => cb.checked = false);
    container.querySelectorAll('.analysis-factor').forEach(cb => cb.checked = false);
    container.querySelector('#select-all-categories').checked = false;

    container.querySelector('#analysis-results').style.display = 'none';
    correlationResults = [];
  }

  // 相関係数表の行クリックイベント
  function setupCorrelationTableEvents() {
    container.addEventListener('click', function(e) {
      const row = e.target.closest('.correlation-row');
      if (row) {
        // 既存の選択をクリア
        container.querySelectorAll('.correlation-row').forEach(r => r.classList.remove('selected'));

        // 新しい行を選択
        row.classList.add('selected');

        const index = parseInt(row.dataset.index);
        selectedCorrelation = correlationResults[index];

        // 対応するグラフを更新（実装では散布図を再描画）
        drawScatterChart();
      }
    });
  }

  // イベントリスナーの設定
  container.querySelector('#btn-execute-analysis').addEventListener('click', executeCorrelationAnalysis);
  container.querySelector('#btn-clear-conditions').addEventListener('click', clearConditions);
  container.querySelector('#btn-export-csv').addEventListener('click', exportToCSV);

  container.querySelector('#btn-export-pdf').addEventListener('click', function() {
    alert('PDF出力機能は開発中です。');
  });

  // 初期化処理
  loadStores();
  setupCategoryCheckboxes();
  setupSelectAllCategories();
  setupCorrelationTableEvents();

  // デフォルト日付の設定
  const today = new Date();
  const oneMonthAgo = new Date(today.getFullYear(), today.getMonth() - 1, today.getDate());

  container.querySelector('#analysis-end-date').value = today.toISOString().split('T')[0];
  container.querySelector('#analysis-start-date').value = oneMonthAgo.toISOString().split('T')[0];
}
